"""Generate report from completed CSV outputs; no refitting or threshold selection."""
from pathlib import Path
import json
import numpy as np
import pandas as pd
ROOT=Path(__file__).resolve().parent

def table(d,cols):
    d=d[cols].copy()
    for c in d.select_dtypes(include='number'):
        d[c]=d[c].map(lambda x:f'{x:.5f}' if pd.notna(x) else 'NA')
    return '| '+' | '.join(cols)+' |\n|'+'|'.join(['---']*len(cols))+'|\n'+'\n'.join('| '+' | '.join(map(str,row))+' |' for row in d.to_numpy())

def main():
    r=pd.read_csv(ROOT/'results.csv');a=pd.read_csv(ROOT/'annual_results.csv');b=pd.read_csv(ROOT/'bootstrap.csv');v=pd.read_csv(ROOT/'robustness.csv');l=pd.read_csv(ROOT/'transitions.csv');meta=json.loads((ROOT/'run_metadata.json').read_text())
    occ=r[r['mode']=='occupancy'];primary=occ[(occ.stage=='confirmed')&(occ.comparator=='weak')&(occ.metric=='return')]
    counts=l[l.to_state.isin([1,2,3])].groupby('to_state').size()
    # Explicit prospective declaration ordering and bounded histories are checked from exports.
    d=pd.read_csv(ROOT/'state_history.csv',index_col=0,parse_dates=[0]);valid=d.state.notna()
    for c in ['damage_date','breadth_date','confirmation_date']:d[c]=pd.to_datetime(d[c])
    assert (d.loc[d.state.ge(2),'damage_date']<d.loc[d.state.ge(2),'breadth_date']).all()
    assert (d.loc[d.state.eq(3),'breadth_date']<d.loc[d.state.eq(3),'confirmation_date']).all()
    assert (d.loc[valid,'damage_date'].dropna()<=d.loc[valid,'damage_date'].dropna().index).all()
    identical=occ[occ.stage.eq('damage')&occ.comparator.eq('matched_damage')]
    assert identical.p.isna().all() and identical.effect.eq(0).all()
    claim=[]
    for stage,prev in [('breadth','damage'),('confirmed','breadth')]:
        z=occ[occ.stage.eq(stage)&occ.metric.eq('return')&occ.comparator.isin([prev,'weak'])]
        robust=v[(v['mode']=='occupancy')&v.stage.eq(stage)&v.metric.eq('return')&v.comparator.isin([prev,'weak'])&v.variant.isin(['delay1','omit_crises'])]
        passes=bool(len(z)==4 and (z.effect>0).all() and (z.bonferroni<.05).all() and (~z.fragile).all() and (robust.effect>0).all())
        claim.append(f'{stage}: '+('passes' if passes else 'does not pass'))
    lines=['# SPY ordered-state-transition study',
    'Executed 2026-10-31. **Null incremental result:** this bounded damage → breadth recovery → price confirmation hypothesis does not establish improved 21- or 63-session return or forward drawdown forecasts. These are exploratory historical conditional-outcome comparisons, not untouched OOS, forecast calibration, trading profitability or causal treatment effects. All CSV return/drawdown effects are decimal fractions: 0.01 is one percentage point.',
    'Confirmed-state mean returns were 0.56% at 21 sessions and 2.25% at 63 sessions, versus 2.25% and 4.92% for weak breadth alone on common eligibility. Price confirmation reduced mean return relative to the breadth-wait stage by 0.50 and 3.95 percentage points. Both differences are uncertain. Breadth recovery had a higher 63-session mean than damage, but did not establish incremental value over weak breadth. Pre-outcome protocol criteria: '+ '; '.join(claim)+'.',
    'Weak breadth (<40% DEV79 above 50DMA) has historically accompanied larger subsequent SPY returns. That is a rebound association, **not proof of positive correlation between breadth level and future returns**. The ordered hypothesis neither overturns that distinction nor validates an original R1 implementation.',
    '## Chronology and definitions\n[PROTOCOL.md](PROTOCOL.md) was written before this study computed outcomes. [SOURCES.md](SOURCES.md) identifies the prior studies and original frozen protocols read. Damage requires current trailing 252-session SPY drawdown <=−10% and weak breadth. Breadth must subsequently improve >=10 points from its damage-declaration value, with five-session mean >=40%. On a still later session, price must be above EMA20 on >=4/5 sessions, with positive five-session return, rising EMA20 and nonincreasing RV20 over five sessions. These are newly fixed hypothesis thresholds, not original R1 rules. They omit external stress and directly measured failed rebounds.',
    'The machine permits only one transition per session. Damage and breadth wait deadlines are 63 and 21 sessions; confirmation remains active for 21 sessions; all episodes expire within 126 sessions. Exact deadline transitions are allowed. Missing required features abort and produce missing state. A terminated episode must observe the damage gate false while idle before rearming. No future trough, later minimum or eventual recovery outcome initializes, resets or gates a declaration. Earlier stages include failed episodes; they are never filtered to successful conversions. States are exclusive, so a prior-stage contrast compares different dates and may reflect changing regimes/time since damage. It does not identify an isolated effect of waiting.',
    f'Across the full feature history there were {counts.get(1,0)} damage declarations, {counts.get(2,0)} breadth transitions and {counts.get(3,0)} confirmations. Only 14 completed confirmation declarations make the confirmed stage fragile. Exported history checks confirm strictly increasing transition timestamps; transition and state ledgers preserve anchor breadth and dates. Episodes may span year boundaries; forward labels may not.',
    '## State outcomes\nMean adjusted-close forward return, negative-return probability and maximum close peak-to-trough drawdown include all eligible occupancy dates, not just declarations. The MDD path includes t..t+h and interim peaks. More positive drawdown effect means less loss. Same-close execution is not assumed; intraday losses are unobserved. Counts are daily dates, runs and greedily spaced h-session windows, none certified independent.\n'+table(occ[occ.comparator.eq('unconditional')],['stage','horizon','metric','n','onsets','nonoverlap_n','mean','baseline_mean','effect','ci_low','ci_high','q','bonferroni']),
    '## Incremental comparisons\nEach stage is compared with its immediate prior stage, weak breadth alone, positive 63-session SPY momentum, unconditional SPY, matched damage and an unordered same-date conjunction. Damage uses unconditional as its prior. All rows, including nulls and undefined sparse estimates, are in results.csv.\n'+table(occ[((occ.stage=='breadth')&(occ.comparator=='damage'))|((occ.stage=='confirmed')&(occ.comparator=='breadth'))|((occ.stage.isin(['breadth','confirmed']))&(occ.comparator=='weak'))],['stage','comparator','horizon','metric','n','effect','ci_low','ci_high','q','bonferroni']),
    'The confirmed-state mean MDD is −4.92% at 21 and −9.51% at 63 sessions, compared with unconditional −4.06% and −7.40%. Relative to breadth-wait dates, drawdown improves by 2.06 points at 21 sessions but only 0.33 at 63; both intervals include zero. No robust lower-path-risk forecast follows from confirmation. Downside probabilities likewise do not establish incremental benefit.',
    '## Matching and support\nControls are contemporaneous DAMAGE-state dates in the same calendar year, current drawdown bin and annualized RV20 bin. Exact strata are fixed; controls receive weights matching target-date stratum shares, with replacement. This uses no future data or eventual conversion. Year conditioning is retrospective sample control, not an online forecast estimator. Matching controls only coarse observed severity, not confounding. Unmatched targets are excluded only from this contrast; target support and every control weight appear in match_support.csv. Damage occupancy against matched damage is an identical-arm diagnostic with zero effect and undefined p-value.\n'+table(occ[occ.stage.isin(['breadth','confirmed'])&occ.comparator.eq('matched_damage')],['stage','horizon','metric','n','unmatched_n','baseline_n','baseline_effective_n','nonoverlap_n','effect','ci_low','ci_high','q']),
    'Most confirmed dates cannot be matched: 161/277 at horizon 21 and 120/231 at horizon 63. Matched results apply only to supported dates and cannot be generalized to all confirmations. Their return effects and MDD effects remain uncertain.',
    '## Transition-date analysis\nPulses use the actual declaration dates. Prior-stage pulses are all earlier-stage declarations, including episodes that never reach the next stage. No paired successful-episode selection is performed. Small numbers make asymptotic intervals particularly unreliable.\n'+table(r[(r['mode']=='pulse')&r.comparator.eq('unconditional')],['stage','horizon','metric','n','onsets','nonoverlap_n','mean','effect','ci_low','ci_high','q']),
    '## Robustness\nWindow sizes and retention are fixed sensitivities, not ranked or selected. delay1 shifts all state/comparator indicators and matching covariates one trading session before attaching the current forward label; this is a delayed predictive observation, not a costed backtest. Crisis omissions exclude signal dates and all labels touching the omitted year because all labels are year-purged. Exact thresholds, rearming and abort behavior remain fixed. Full lag, damage-threshold, window, retention, delay, crisis and leave-one-year-out results are in robustness.csv.\n'+table(v[(v['mode']=='occupancy')&v.stage.eq('confirmed')&v.comparator.eq('weak')&v.metric.eq('return')&v.variant.isin(['wait42_10','wait84_42','retention10','retention42','damage15','delay1','lag126','omit_crises','omit_2008','omit_2009','omit_2020','omit_2022'])],['variant','horizon','n','nonoverlap_n','effect','ci_low','ci_high','q']),
    '## Year-by-year historical stability\nAnnual results retain the fixed machine, without annual threshold fitting or rule selection. Each label must finish within its signal calendar year. All years 2006–2025, including empty years, are exported in annual_results.csv. They form chronological historical diagnostics; prior human inspection of 2017–2025 prevents an untouched OOS claim. Dates are sparse, years are dependent, and apparent sign consistency is not a significance test.\n'+table(a[(a['mode']=='occupancy')&a.stage.eq('confirmed')&a.comparator.eq('weak')&a.metric.eq('return')],['year','horizon','n','nonoverlap_n','mean','baseline_mean','effect','ci_low','ci_high']),
    '## Uncertainty and multiplicity\nMarginal paired calendar influence-function HAC intervals use Bartlett lag max(63,2h), preserving zeros at calendar gaps and shared observations. Matching uses weighted control influence scores. At least five dates per arm are required for inference, but that is not an adequacy claim. Fewer than 20 runs or nonoverlap windows in either arm flags fragile. Small-event HAC can be overconfident and cannot repair retrospective hypothesis formation. BH is reported with limited guarantees under dependent tests; Bonferroni is the conservative dependence-robust adjustment. CIs are not simultaneous.',
    f'All {meta["finite_pooled_tests"]} finite pooled tests across occupancy/pulses, stages, comparators, two horizons and three outcomes share one BH/Bonferroni family. All {meta["finite_annual_tests"]} finite annual contrasts share a separate family; all {v.p.notna().sum()} finite sensitivity contrasts share another. Undefined estimates remain NA. No significance is inferred from numerical residue in identical-arm contrasts.',
    'Paired circular moving-block bootstrap uses 1000 fixed-seed replicates at 63/126 sessions for breadth and confirmation versus prior, weak and unconditional. It preserves within-block overlap but is also imperfect with few episodes; resamples with <5 dates per arm are discarded and counted. Intervals are marginal percentile intervals and not multiple-comparison adjusted. Matched results are not bootstrapped.\n'+table(b[b.stage.eq('confirmed')&b.comparator.eq('weak')],['horizon','metric','block','valid_replicates','ci_low','ci_high']),
    '## Data and reproducibility\nSPY and retrospective DEV79 adjusted closes are reused locally. Full input hashes, coverage, protocol/source/helper/test hashes and package versions are in run_metadata.json. data_quality.csv records missing cells and large moves without filtering. No forward fill or backfill is used. Every breadth observation needs complete trailing SMA50 prices per constituent and at least 20 eligible stocks. DEV79 has historical survivorship bias and prices have current-vintage adjustments: temporal code causality does not make the universe or vintage point-in-time correct. DEV87 is unavailable in prior work; no cross-universe replication or independent price certification is claimed.',
    'Reproduce from the workspace:\n```sh\n/opt/mts/.venv/bin/python experiments/spy_recovery_sequence_20261031/study.py > experiments/spy_recovery_sequence_20261031/run.log 2>&1\n/opt/mts/.venv/bin/python -m pytest -q experiments/spy_recovery_sequence_20261031/test_study.py > experiments/spy_recovery_sequence_20261031/tests.log 2>&1\n/opt/mts/.venv/bin/python experiments/spy_recovery_sequence_20261031/report.py\n```\nTests cover future perturbation, prefix invariance, strict ordering, inclusive deadlines, expiry/rearming, hard cap, missing data, delayed state alignment, drawdown arithmetic, year purging, matching weights/support, paired inference and identical-arm numerical handling. report.py additionally audits exported ordering and identical-arm outputs. Execution is bounded local research; no GA, paid data, MTS edits, other-project edits or long certification. Artifacts include features, signals, state_history, transitions, outcomes, results, annual_results, robustness, bootstrap, match_support, data_quality, run_metadata, run.log and tests.log.']
    (ROOT/'REPORT.md').write_text('\n\n'.join(lines)+'\n')
    print('REPORT.md generated; exported timestamp and identical-arm audits passed.')
if __name__=='__main__':main()
